        "**زاویه‌ها:** زاویهٔ راست ۹۰ درجه، زاویهٔ نیم‌صفحه ۱۸۰ درجه و زاویهٔ کامل ۳۶۰ درجه است. زاویه‌های متقابل به رأس برابرند و زاویه‌های مجاور روی یک خط مجموع ۱۸۰ درجه دارند.",
        "**موازی‌ها:** اگر دو خط موازی با یک خط مورب قطع شوند، زاویه‌های متناظر و متناوب داخلی برابرند و زاویه‌های داخلی هم‌جهت مکمل‌اند.",
