        "**استدلال:** از داده‌ها و تعریف‌ها شروع کن؛ هر نتیجه را با یک قضیه یا خاصیت توجیه کن. شکل ظاهری به‌تنهایی اثبات نیست.",
        "**هم‌نهشتی و تشابه:** هم‌نهشتی یعنی شکل‌ها هم‌اندازه و هم‌شکل‌اند؛ تشابه یعنی زاویه‌های متناظر برابر و ضلع‌های متناظر متناسب‌اند."
