    "8-6-1": {
      "grade": "8",
      "chapter": "مثلث",
      "title": "رابطه ضلع‌ها و زاویه‌ها",
      "intro": "در هندسه، شکل فقط یک تصویر نیست؛ مجموعه‌ای از تعریف‌ها، ویژگی‌ها و رابطه‌های قابل استدلال است. برای حل مسئله ابتدا داده‌های شکل را به زبان دقیق ریاضی تبدیل می‌کنیم، سپس قضیهٔ مناسب را با ذکر شرط‌هایش به کار می‌بریم.",
      "body": [
        "**تعریف‌ها را دقیق بخوان:** مثلاً ضلع، رأس، قطر، ارتفاع، میانه، نیمساز و عمودمنصف مفاهیم متفاوتی‌اند و نباید جای یکدیگر استفاده شوند.",
        "**زاویه‌ها:** زاویهٔ راست ۹۰ درجه، زاویهٔ نیم‌صفحه ۱۸۰ درجه و زاویهٔ کامل ۳۶۰ درجه است. زاویه‌های متقابل به رأس برابرند و زاویه‌های مجاور روی یک خط مجموع ۱۸۰ درجه دارند.",
        "**موازی‌ها:** اگر دو خط موازی با یک خط مورب قطع شوند، زاویه‌های متناظر و متناوب داخلی برابرند و زاویه‌های داخلی هم‌جهت مکمل‌اند.",
        "**مثلث:** مجموع زاویه‌های داخلی هر مثلث ۱۸۰ درجه است. در مثلث متساوی‌الساقین، زاویه‌های روبه‌روی ساق‌های برابر، برابرند.",
        "**چندضلعی:** مجموع زاویه‌های داخلی nضلعی برابر (n−۲)×۱۸۰ درجه است؛ اگر منتظم باشد، هر زاویهٔ داخلی برابر همین مقدار تقسیم بر n است.",
        "**استدلال:** از داده‌ها و تعریف‌ها شروع کن؛ هر نتیجه را با یک قضیه یا خاصیت توجیه کن. شکل ظاهری به‌تنهایی اثبات نیست.",
        "**هم‌نهشتی و تشابه:** هم‌نهشتی یعنی شکل‌ها هم‌اندازه و هم‌شکل‌اند؛ تشابه یعنی زاویه‌های متناظر برابر و ضلع‌های متناظر متناسب‌اند."
      ],
      "example": "در یک 7ضلعی، مجموع زاویه‌های داخلی برابر (7−۲)×۱۸۰=900 درجه است. اگر منتظم باشد، هر زاویه 900÷7=128.571 درجه خواهد بود.",
      "tip": "در چندضلعی منتظم، مجموع زاویه‌های خارجی همیشه ۳۶۰ درجه است؛ اندازهٔ هر زاویهٔ خارجی ۳۶۰ تقسیم بر تعداد ضلع‌هاست.",
      "content_status": "بازنویسی آموزشی تفصیلی؛ نیازمند تطبیق نهایی با چاپ رسمی کتاب درسی",
      "source": "تألیف آموزشی مستقل؛ مرجع سرفصل و نسخهٔ رسمی: https://chap.sch.ir/ و https://www.roshd.ir/riazi",
      "practice_question": "[شناسه 8-6-1 | درس رابطه ضلع‌ها و زاویه‌ها] یک چندضلعی منتظم 7 ضلعی داریم. (الف) مجموع زاویه‌های داخلی را بیابید. (ب) اندازهٔ هر زاویهٔ داخلی و هر زاویهٔ خارجی را حساب کنید. (ج) تعداد قطرهای آن را به دست آورید.",
      "solution_steps": [
        "مجموع زاویه‌های داخلی: (7−۲)×۱۸۰=900 درجه.",
        "چون چندضلعی منتظم است، هر زاویهٔ داخلی: 900÷7=128.571 درجه.",
        "هر زاویهٔ خارجی: ۳۶۰÷7=51.4286 درجه؛ یا ۱۸۰−128.571.",
        "تعداد قطرها: n(n−۳)÷۲ = 7×4÷۲ = 14."
      ],
      "final_answer": "مجموع داخلی: ۹۰۰°؛ هر داخلی: ۱۲۸٫۵۷۱۴۲۸۵۷۱۴۲۸۵۸°؛ هر خارجی: ۵۱٫۴۲۸۵۷۱۴۲۸۵۷۱۴۳°؛ تعداد قطرها: ۱۴.",
      "exercise_status": "تمرین اختصاصی مرتبط با مبحث؛ مراحل و پاسخ محاسبه‌شده"
    },
