        "**ترتیب حل:** ابتدا پرانتزها را باز کن، جمله‌های هم‌نوع را جمع کن، جمله‌های دارای مجهول را در یک طرف و ثابت‌ها را در طرف دیگر قرار بده.",
        "**نامعادله:** در نامعادله، ضرب یا تقسیم دو طرف در عدد منفی جهت علامت را برعکس می‌کند؛ این نکته با معادله تفاوت مهمی دارد.",
        "**جواب‌سنجی:** مقدار به‌دست‌آمده را در معادلهٔ اصلی جای‌گذاری کن؛ دو طرف باید برابر شوند.",
        "**دامنهٔ جواب:** اگر مسئله دربارهٔ تعداد، طول یا زمان است، جواب باید با محدودیت‌های واقعی مسئله سازگار باشد."
